import io.reactivex.rxjava3.core.Observable;
import io.reactivex.rxjava3.core.ObservableSource;
import io.reactivex.rxjava3.core.Observer;
import io.reactivex.rxjava3.disposables.Disposable;
import io.reactivex.rxjava3.functions.Function;
import io.reactivex.rxjava3.observers.TestObserver;

// Reproduction of https://github.com/ReactiveX/RxJava/issues/7597:
// a source that emits synchronously during subscribeActual *before*
// its onSubscribe has a chance to allocate SwitchMapInnerObserver.queue.
public class SwitchMapNpeRepro {
    public static void main(String[] args) {
        Observable<Integer> emitsBeforeOnSubscribe = new Observable<Integer>() {
            @Override
            protected void subscribeActual(Observer<? super Integer> observer) {
                // Emit before calling onSubscribe: queue would still be null
                observer.onNext(42);
                observer.onSubscribe(Disposable.empty());
                observer.onComplete();
            }
        };

        TestObserver<Integer> to = Observable.just(1)
            .hide()
            .switchMap(new Function<Integer, ObservableSource<Integer>>() {
                @Override
                public ObservableSource<Integer> apply(Integer v) {
                    return emitsBeforeOnSubscribe;
                }
            })
            .test();

        to.assertResult(42);
        System.out.println("OK: no NPE, value dropped safely before subscription was established");
    }
}

